function Icon({ name, size = 15, className }) {
  const d = ICONS[name];
  if (!d) return null;
  return (
    <svg className={className} viewBox="0 0 256 256" width={size} height={size} fill="currentColor" aria-hidden="true" focusable="false">
      <path d={d} />
    </svg>
  );
}


function waitMonaco() {
  if (!window.__monacoPromise) {
    window.__monacoPromise = new Promise((resolve) => {
      const t0 = Date.now();
      const check = () => {
        if (window.monaco) return resolve(window.monaco);
        if (Date.now() - t0 > 30000) return resolve(null);
        setTimeout(check, 60);
      };
      check();
    });
  }
  return window.__monacoPromise;
}

