function md(src) {
  return DOMPurify.sanitize(marked.parse(src || ''));
}

// fuhhh opencode-style paced reveal: targets grow w/ deltas but chars flow in
// smoothly (burst catch-up), caret sits at da write head son :sob:
function StreamBody({ text, typing }) {
  const start = useRef(typing ? 0 : text.length);
  const [shown, setShown] = useState(start.current);
  const hostRef = useRef(null);
  const everTyped = useRef(typing);
  const revealedRef = useRef(false);
  const target = text.length;
  useEffect(() => {
    if (shown >= target) return undefined;
    let raf = 0;
    raf = requestAnimationFrame(() => {
      setShown((s) => {
        const gap = target - s;
        if (gap <= 0) return s;
        return s + Math.min(140, Math.max(1, Math.ceil(gap / 8)));
      });
    });
    return () => cancelAnimationFrame(raf);
  });
  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host || shown >= target) return;
    let el = host;
    while (true) {
      const kid = el.lastElementChild;
      if (!kid || /^(img|br|hr|svg|video|canvas|input|select|table)$/i.test(kid.tagName)) break;
      el = kid;
    }
    const caret = document.createElement('span');
    caret.className = 'type-caret';
    el.appendChild(caret);
  });
  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host || revealedRef.current || !everTyped.current || shown < target) return;
    revealedRef.current = true;
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    let i = 0;
    const walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    for (const n of nodes) {
      const frag = document.createDocumentFragment();
      n.nodeValue.split(/(\s+)/).forEach((p) => {
        if (!p) return;
        if (/^\s+$/.test(p)) { frag.appendChild(document.createTextNode(p)); return; }
        const sp = document.createElement('span');
        sp.className = 'w';
        sp.style.animationDelay = `${i++ * 34}ms`;
        sp.textContent = p;
        frag.appendChild(sp);
      });
      n.replaceWith(frag);
    }
  });
  return (
    <div className="md md-stream" ref={hostRef} dangerouslySetInnerHTML={{ __html: md(text.slice(0, shown)) }} />
  );
}

const escHtml = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

function TypeText({ text, className }) {
  const [shown, setShown] = useState(0);
  useEffect(() => {
    if (shown >= text.length) return undefined;
    let raf = 0;
    raf = requestAnimationFrame(() => setShown((s) => Math.min(text.length, s + Math.min(4, Math.max(1, Math.ceil((text.length - s) / 8))))));
    return () => cancelAnimationFrame(raf);
  });
  return (
    <span className={className}>
      {text.slice(0, shown)}
      {shown < text.length && <span className="type-caret" />}
    </span>
  );
}

function monacoLang(name) {
  const ex = name.split('.').pop().toLowerCase();
  const map = {
    js: 'javascript', jsx: 'javascript', mjs: 'javascript', cjs: 'javascript',
    ts: 'typescript', tsx: 'typescript',
    json: 'json', py: 'python', rb: 'ruby', go: 'go', rs: 'rust',
    c: 'cpp', h: 'cpp', hpp: 'cpp', cpp: 'cpp', cc: 'cpp',
    java: 'java', cs: 'csharp', php: 'php', html: 'html', htm: 'html',
    css: 'css', scss: 'scss', less: 'less',
    md: 'markdown', markdown: 'markdown', yml: 'yaml', yaml: 'yaml',
    toml: 'ini', ini: 'ini', xml: 'xml', sh: 'shell', ps1: 'powershell',
    bat: 'bat', sql: 'sql', vue: 'html', svelte: 'html', txt: 'plaintext',
  };
  return map[ex] || 'plaintext';
}

// ---------------- custom dropdown (dark glass) ----------------

function Dropdown({ value, options, onChange, id, footer }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', onDoc);
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDoc); document.removeEventListener('keydown', onKey); };
  }, [open]);
  const selected = options.find((o) => o.value === value);
  return (
    <div className={`dropdown${open ? ' open' : ''}`} id={id} ref={ref}>
      <button type="button" className="dropdown-btn" onClick={() => setOpen((o) => !o)}>
        <span className="dropdown-value">{selected ? selected.label : 'select…'}</span>
        <Icon className="dropdown-chev" name="caretDown" size={12} />
      </button>
      {open && (
        <div className="dropdown-menu">
          {options.map((o) => (
            <button key={o.value} type="button" className={`dropdown-item${o.value === value ? ' selected' : ''}`} onClick={() => { onChange(o.value); setOpen(false); }}>
              <span className="dropdown-item-text">
                <span className="dropdown-item-label">{o.label}</span>
                {o.desc && <span className="dropdown-item-desc">{o.desc}</span>}
              </span>
              {o.value === value && <span className="dropdown-item-check">
                <Icon name="check" size={13} />
              </span>}
            </button>
          ))}
          {footer && <div className="dropdown-foot">{footer}</div>}
        </div>
      )}
    </div>
  );
}

let idSeq = 0;
const nextId = () => `i${++idSeq}`;

// ---------------- tool card ----------------
function ToolCard({ item, onToggle }) {
  // fuhhh status glyph line not a card cuhh :sob:
  const cls = item.stopped ? 'stopped' : item.error ? 'error' : item.done ? 'ok' : 'running';
  const time = item.done && item.ms ? fmtDur(item.ms) : '';
  return (
    <div className={`tool-card ${cls}${item.open ? ' open' : ''}`}>
      <div className="tool-head" onClick={onToggle}>
        {cls === 'ok' ? (
          <span className="tool-glyph check"><Icon name="check" size={12} /></span>
        ) : cls === 'error' ? (
          <span className="tool-glyph cross"><Icon name="x" size={12} /></span>
        ) : cls === 'stopped' ? (
          <span className="tool-glyph dash">–</span>
        ) : (
          <span className="tool-glyph dot" />
        )}
        <span className="tool-name">{item.name}</span>
        {time ? <span className="tool-time">{time}</span> : null}
        <Icon className="tool-chev" name="caretDown" size={10} />
      </div>
      {item.open && (
        <div className="tool-body">
          <div className="tool-label">args</div>
          <pre className="tool-code">{item.args || '{}'}</pre>
          {item.result ? (<><div className="tool-label">result</div><pre className="tool-code">{item.result}</pre></>) : null}
        </div>
      )}
    </div>
  );
}

const ACT_META = [
  { re: /^(shell|pwsh|cmd|bash)$/, meta: (a) => { const c = String(a.command || '').trim(); return c ? (c.length > 74 ? c.slice(0, 74) + '…' : c) : 'PowerShell'; } },
  { re: /^(read_file|list_dir|read)$/, meta: (a) => baseName(a.path) },
  { re: /^glob$/, meta: (a) => baseName(String(a.pattern || '').replace(/[\\/]+/g, '·') || '') || 'pattern' },
  { re: /^grep$/, meta: (a) => baseName(a.path) || String(a.pattern || '').slice(0, 40) },
  { re: /^(write_file|edit_file|delete_file)$/, meta: (a) => baseName(a.path) },
  { re: /^(strings|hexdump)$/, meta: (a) => baseName(a.path || a.file) },
  { re: /^fetch_url$/, meta: (a) => { try { return new URL(String(a.url || '')).hostname; } catch { return 'url'; } } },
  { re: /^mcp_status$/, meta: () => 'status' },
];

function baseName(p) {
  const s = String(p || '').replace(/[\\/]+$/, '');
  const m = s.match(/[^\\/:]+$/);
  return m ? m[0] : s;
}

// fuhhh compact durs, no more "a few seconds" essays son :sob:
const fmtDur = (ms) => ms < 1100 ? '1s' : ms < 3000 ? `${(ms / 1000).toFixed(1)}s` : `${Math.round(ms / 1000)}s`;

function ToolGroup({ tools }) {
  const [open, setOpen] = useState(true);
  const doneCount = tools.filter((t) => t.done || t.error || t.stopped).length;
  const fin = doneCount === tools.length;
  return (
    <div className={`tool-group${fin ? ' fin' : ''}`}>
      <button className="tg-head" aria-expanded={open} onClick={() => setOpen(!open)}>
        <span className="tg-live" />
        <span className="tg-title">{fin ? 'Finished' : 'Working'}</span>
        <span className="tg-count">{doneCount}/{tools.length}</span>
        <Icon className="tg-chev" name="caretDown" size={12} />
      </button>
      <div className={`tg-fold${open ? '' : ' shut'}`}>
        <div>
          <div className="tg-steps">
            {tools.map((tool, i) => <ToolStep key={tool.id || i} tool={tool} />)}
          </div>
        </div>
      </div>
    </div>
  );
}

function ToolStep({ tool }) {
  const [open, setOpen] = useState(false);
  let args = {};
  try { args = JSON.parse(tool.args || '{}') || {}; } catch {}
  const cat = ACT_META.find((c) => c.re.test(tool.name));
  const meta = cat ? cat.meta(args) : '';
  const running = !tool.done && !tool.error && !tool.stopped;
  const failed = tool.error || tool.stopped;
  const time = tool.done && tool.ms ? fmtDur(tool.ms) : '';
  return (
    <div className={`tg-step${running ? ' run' : ''}${failed ? ' failed' : ''}`} data-open={open ? '' : undefined}>
      <button className="tg-sh" onClick={() => setOpen(!open)}>
        <span className="tg-bdg">{failed ? <Icon name="x" size={13} /> : <Icon name="check" size={12} />}</span>
        <span className="tg-name">{tool.name}</span>
        {meta ? <span className="tg-arg" title={meta}>{meta}</span> : null}
        <span className="tg-sp" />
        <span className="tg-dur">{running ? 'working' : failed ? 'failed' : time}</span>
        <Icon className="tg-chev" name="caretDown" size={11} />
      </button>
      <div className="tg-det">
        <div>
          <div className="tg-dd">
            <b>args</b>
            <pre>{tool.args || '{}'}</pre>
            {tool.result ? <><b>{failed ? 'error' : 'result'}</b><pre>{tool.result}</pre></> : null}
          </div>
        </div>
      </div>
    </div>
  );
}

// ---------------- diff summary card ----------------

// fuhhh opencode-style file chip instead of emoji soup son :sob: +5 -7 counts like opencode
const extTag = (n) => String(n || '').split('.').pop().toLowerCase().slice(0, 5);

function DiffFileRow({ d }) {
  const [open, setOpen] = useState(false);
  const seg = String(d.file || '').split(/[\\/]/);
  const nm = seg.pop() || d.file;
  const dir = seg.join('/');
  return (
    <div className="diff-file-card">
      <div className="diff-file-row">
        <span className="diff-ext">{extTag(nm) || 'file'}</span>
        <div className="diff-file-meta" title={d.file}>
          <span className="diff-file-name">{nm}</span>
          {dir ? <span className="diff-file-dir"> {dir}/</span> : null}
        </div>
        {d.added ? <span className="diff-add-count">+{d.added}</span> : null}
        {d.removed ? <span className="diff-del-count">−{d.removed}</span> : null}
        <div className="diff-btns">
          <button className="diff-btn" onClick={() => setOpen((o) => !o)}>Review</button>
          <button className="diff-btn" onClick={() => { V.openPath(d.file); }}>Open</button>
        </div>
      </div>
      {open && d.lines && d.lines.length ? (
        <div className="diff-body">
          {d.lines.map((ln, idx) => (
            <div key={idx} className={`diff-line ${ln.t === '+' ? 'add' : ln.t === '-' ? 'del' : 'ctx'}`} style={{ animationDelay: `${Math.min(idx, 30) * 16}ms` }}>
              <span className="diff-no">{ln.t === '-' ? (ln.a ?? '') : (ln.b ?? ln.a ?? '')}</span>
              <span className="diff-sign">{ln.t === ' ' ? '' : ln.t}</span>
              <span className="diff-text">{ln.text}</span>
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function WriteCard({ tool }) {
  // fuhhh write rows: same file chip + numbered preview as diff rows :broken_heart:
  const [open, setOpen] = useState(false);
  let args = {};
  try { args = JSON.parse(tool.args || '{}') || {}; } catch {}
  const seg = String(args.path || '').split(/[\\/]/);
  const nm = seg.pop() || '';
  const dir = seg.join('/');
  const running = !tool.done && !tool.error && !tool.stopped;
  const failed = tool.error || tool.stopped;
  const content = String(args.content ?? '');
  return (
    <div className={failed ? 'diff-card fail' : 'diff-card'}>
      <div className="diff-sum">
        <span className="diff-s1 diff-head">
          {running ? <span className="tool-glyph dot" />
            : failed ? <span className="tool-glyph cross"><Icon name="x" size={12} /></span>
            : <span className="tool-glyph check"><Icon name="check" size={12} /></span>}
          <span className={`tool-name${running ? ' think-word' : ''}`}>{tool.name}</span>
          {running ? null : tool.done && !failed ? <span className="tool-time">{fmtDur(tool.ms)}</span> : null}
        </span>
      </div>
      {nm ? (
        <div className="diff-file-card">
          <div className="diff-file-row">
            <span className="diff-ext">{extTag(nm) || 'file'}</span>
            <div className="diff-file-meta" title={args.path}>
              <span className="diff-file-name">{nm}</span>
              {dir ? <span className="diff-file-dir"> {dir}/</span> : null}
            </div>
            <div className="diff-btns">
              <button className="diff-btn" onClick={() => setOpen((o) => !o)}>Review</button>
              <button className="diff-btn" onClick={() => { if (args.path) V.openPath(args.path); }}>Open</button>
            </div>
          </div>
          {open ? (
            content || tool.result ? (
              <div className="diff-body">
                {content ? content.split(/\r?\n/).slice(0, 60).map((ln, idx) => (
                  <div key={idx} className="diff-line add" style={{ animationDelay: `${Math.min(idx, 30) * 16}ms` }}>
                    <span className="diff-no" />
                    <span className="diff-sign">+</span>
                    <span className="diff-text">{ln || ' '}</span>
                  </div>
                )) : null}
                {tool.result ? <div className="tool-label" style={{ padding: '6px 12px' }}>{failed ? 'error' : 'result'}</div> : null}
                {tool.result ? <pre className="tool-code" style={{ margin: 0 }}>{tool.result}</pre> : null}
              </div>
            ) : (
              <div className="diff-body"><div className="diff-line ctx"><span className="diff-no" /><span className="diff-sign"> </span><span className="diff-text">
                {content === '' && tool.name === 'write_file' ? '(empty file)' : content === '' ? '(no content)' : ''}
              </span></div></div>
            )
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

const cleanToolProse = (t) => String(t)
  .replace(/<\|?tool_calls\b[^>]*>[\s\S]*?(?:<\/\|?tool_calls\b[^>]*>|$)/gi, '')
  .replace(/<\|?\/?\s*(?:invoke|parameter)\b[^>]*>/gi, '')
  .replace(/<function=[^\s=<>]+>[\s\S]*?(?:<\/function\s*>|$)/gi, '')
  .replace(/<\/?\|?(?:invoke|parameter|tool_calls)\b[^>]*>/gi, '')
  .trim();

// ---------------- task list ----------------
function TaskList({ tasks }) {
  if (!tasks || !tasks.length) return null;
  const done = tasks.filter(t => t.completed).length;
  const total = tasks.length;
  const allDone = done === total;

  return (
    <div className={`task-list-card ${allDone ? 'all-done' : ''}`}>
      <div className="task-list-head">
        <div className="task-list-icon">
          <Icon name="check" size={14} />
        </div>
        <span className="task-list-label">Task plan</span>
        <span className={`task-list-status${allDone ? ' done' : ''}`}>{done}/{total} done</span>
      </div>
      <div className="task-items">
        {tasks.map((t, i) => (
          <div key={i} className={`task-item ${t.completed ? 'completed' : ''}`}>
            <div className="task-check">
              {t.completed ? (
                <Icon name="check" size={12} />
              ) : (
                <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /></svg>
              )}
            </div>
            <span className="task-text">{t.text}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ---------------- message items ----------------

function MsgActions({ item, onRestore, onRetry }) {
  const [vote, setVote] = useState(0);
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(item.content || '');
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    } catch {}
  };
  return (
    <div className="msg-actions">
      <button className={`msg-restore${vote === 1 ? ' on' : ''}`} title="Good response" aria-label="Like" onClick={() => setVote((v) => v === 1 ? 0 : 1)}><Icon name="thumbUp" size={12} /></button>
      <button className={`msg-restore${vote === -1 ? ' on' : ''}`} title="Bad response" aria-label="Dislike" onClick={() => setVote((v) => v === -1 ? 0 : -1)}><Icon name="thumbDown" size={12} /></button>
      <button className="msg-restore" title={copied ? 'Copied' : 'Copy message'} aria-label="Copy message" onClick={copy}><Icon name={copied ? 'check' : 'copy'} size={12} /></button>
      <button className="msg-restore" title="Retry this turn" aria-label="Retry" onClick={() => onRetry && onRetry(item)}><Icon name="retry" size={12} /></button>
      {item.turn && <button className="msg-restore" title="Restore code and messages to this point" aria-label="Restore to this point" onClick={() => onRestore && onRestore(item)}><Icon name="clock" size={12} /></button>}
    </div>
  );
}

function Message({ item, tasks, onRestore, onContinue, onRetry }) {
  if (item.kind === 'user') {
    return (
      <div className="msg-wrap msg-user">
        <div className="msg-row">
          <div className="msg-role">You</div>
          <div className="msg-bubble">
            {item.image && <img className="msg-img" src={item.image} alt="pasted image" onClick={() => window.open(item.image, '_blank')} />}
            {item.content}
          </div>
          {item.turn && <button className="msg-restore" title="Restore code and messages to this point" aria-label="Restore to this point" onClick={() => onRestore && onRestore(item)}><Icon name="clock" size={12} /></button>}
        </div>
      </div>
    );
  }
  if (item.kind === 'assistant') {
    const thinking = item.streaming && !item.content && item.tools.length === 0;
    const emptyFinal = !item.streaming && !item.content && item.tools.length === 0;
    const blocksRaw = item.blocks && item.blocks.length ? item.blocks
      : [
          ...item.tools.filter(t => t.name !== 'task_list').map(t => ({ t: 'tool', tool: t })),
          ...(item.diffs && item.diffs.length ? [{ t: 'diff', diff: item.diffs }] : []),
          { t: 'text', text: item.content },
        ];
    const blocks = [];
    for (const b of blocksRaw) {
      if (b.t === 'tool' && b.tool.name !== 'task_list' && !/^(write_file|edit_file|delete_file)$/.test(b.tool.name)) {
        const prev = blocks[blocks.length - 1];
        if (prev && prev.t === 'toolgroup') prev.tools.push(b.tool);
        else blocks.push({ t: 'toolgroup', tools: [b.tool] });
      } else blocks.push(b);
    }
    const lastTextIdx = (() => { let idx = -1; for (let i = 0; i < blocks.length; i++) if (blocks[i].t === 'text') idx = i; return idx; })();

    return (
      <div className={`msg-wrap msg-assistant${item.streaming ? ' streaming' : ''}`}>
        {blocks.map((b, bi) => {
          if (b.t === 'toolgroup') {
            return <div key={bi} className="msg-row"><ToolGroup tools={b.tools} /></div>;
          }
          if (b.t === 'tool') {
            if (b.tool.name === 'task_list') {
              return (
                <div key={bi} className="msg-row">
                  <TaskList tasks={tasks} />
                </div>
              );
            }
            if (/^(write_file|edit_file|delete_file)$/.test(b.tool.name)) {
              return <div key={bi} className="msg-row"><WriteCard tool={b.tool} /></div>;
            }
            return <div key={bi} className="msg-row"><ToolGroup tools={[b.tool]} /></div>;
          }
          if (b.t === 'diff') {
            const diffs = Array.isArray(b.diff) ? b.diff : [b.diff];
            const ta = diffs.reduce((s, d) => s + (d.added || 0), 0);
            const trr = diffs.reduce((s, d) => s + (d.removed || 0), 0);
            return (
              <div key={bi} className="msg-row">
                <div className="msg-diff diff-card">
                  <div className="diff-sum">
                    <span className="diff-s1">{diffs.length} file{diffs.length > 1 ? 's' : ''} changed</span>
                    <span className="diff-add-count">+{ta}</span>
                    <span className="diff-del-count">−{trr}</span>
                    {item.turn && onRestore && <button className="diff-undo" title="Undo the changes from this turn" onClick={() => onRestore(item)}>↺ Undo</button>}
                  </div>
                  {diffs.map((d) => <DiffFileRow key={d.id} d={d} />)}
                </div>
              </div>
            );
          }
          return (
            <div key={bi} className="msg-row">
              {bi === 0 && <div className="msg-role msg-who">{sbxAnchor('msg-av')}<span>Oxygen</span></div>}
              {bi === 0 && item.streaming && (b.text || '').trim() ? <div className="act-row act-thought"><span className="tool-glyph dot" /><span className="tool-name think-word">Thought</span></div> : null}
              <div className="msg-body">
                {bi === 0 && thinking ? <ThinkingDots />
                  : bi === 0 && emptyFinal ? <span className="no-output">The agent returned no visible output.</span>
                  : bi === lastTextIdx ? <StreamBody text={cleanToolProse(b.text || '')} typing={!!item.streaming} />
                  : <div className="md" dangerouslySetInnerHTML={{ __html: md(cleanToolProse(b.text || '')) }} />}
              </div>
              {bi === lastTextIdx && item.turn && <MsgActions item={item} onRestore={onRestore} onRetry={onRetry} />}
            </div>
          );
        })}
      </div>
    );
  }
  return (
    <div className="msg-wrap msg-error">
      <div className="msg-row er-row">
        <div className="er-flat">
          <span className="tool-glyph cross"><Icon name="x" size={12} /></span>
          <span className="tool-name">error</span>
          <span className="er-detail" title={item.content}>{item.content}</span>
          {onContinue && <button className="er-cont" title="Continue in a new session (history is carried over)" onClick={() => onContinue()}>continue</button>}
        </div>
      </div>
    </div>
  );
}

// ---------------- rail ----------------

const timeAgo = (iso) => {
  if (!iso) return '';
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (m < 1) return 'now';
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  const d = Math.floor(h / 24);
  return d === 1 ? '1d' : `${d}d`;
};

function SbxIcon({ size = 19, children }) {
  return (
    <svg className="sbx-ico" viewBox="0 0 24 24" width={size} height={size} aria-hidden="true">
      {children}
    </svg>
  );
}

const sbxAnchor = (cls) => (
  <svg className={cls} viewBox="0 0 26 30" aria-hidden="true">
    <circle cx="13" cy="4.5" r="2.8" />
    <path d="M13 7.5V28M7 12h12M2.5 19c.6 5.5 5.5 9 10.5 9s9.9-3.5 10.5-9" />
    {cls === 'sbx-brand-anchor' ? <path d="m1 21 1.5-2.5L5 20.5M25 21l-1.5-2.5-2.5 2" /> : null}
  </svg>
);

function SeaWaves({ className = 'sbx-sea' }) {
  const ref = useRef(null);
  useEffect(() => {
    const cv = ref.current;
    if (!cv) return undefined;
    const ctx = cv.getContext('2d');
    const waves = [
      { y: 30, a: 6, k: 1.8, v: 1.1, ph: 0, fill: '#d7d2c2' },
      { y: 56, a: 7, k: 2.2, v: 1.3, ph: 2.1, fill: '#e6e0cf' },
      { y: 84, a: 6, k: 1.6, v: 1, ph: 4.2, fill: '#dcd7c7' },
    ];
    let W = 0;
    let H = 0;
    let raf = 0;
    const calm = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const size = () => {
      const d = Math.min(devicePixelRatio || 1, 2);
      W = cv.clientWidth;
      H = cv.clientHeight;
      cv.width = Math.max(1, Math.round(W * d));
      cv.height = Math.max(1, Math.round(H * d));
      ctx.setTransform(d, 0, 0, d, 0, 0);
    };
    const ro = new ResizeObserver(size);
    ro.observe(cv);
    size();
    const t0 = performance.now();
    const draw = (now) => {
      const t = calm ? 0 : (now - t0) / 1000;
      ctx.clearRect(0, 0, W, H);
      ctx.lineWidth = 3;
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#16130e';
      for (const l of waves) {
        const f = (2 * Math.PI / 260) * l.k;
        ctx.beginPath();
        for (let x = -10; x <= W + 10; x += 10) {
          const y = l.y + l.a * Math.sin(f * x + t * l.v + l.ph) + l.a * 0.45 * Math.sin(f * 2.3 * x - t * l.v * 0.7 + l.ph * 1.7);
          if (x === -10) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.lineTo(W + 10, H + 10);
        ctx.lineTo(-10, H + 10);
        ctx.closePath();
        ctx.fillStyle = l.fill;
        ctx.fill();
        ctx.stroke();
      }
      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => { cancelAnimationFrame(raf); ro.disconnect(); };
  }, []);
  return <canvas className={className} ref={ref} aria-hidden="true" />;
}

function Sidebar({ userEmail, onSignOut, onNew, onMcp, onFiles, onBrowser, onTools, onMemory, bgList, onStopBg, sessions, currentId, onPick, onDelete, onClear, mcpActive, toolsActive, filesActive, browserActive, sbWidth, sbHidden, sbToggle, onResizeStart }) {
  const initial = (userEmail || 'a').charAt(0).toUpperCase();
  const [q, setQ] = useState('');
  const [pinned, setPinned] = useState(() => {
    try {
      const v = JSON.parse(localStorage.getItem('vulner.pinned') || '[]');
      return new Set(Array.isArray(v) ? v : []);
    } catch { return new Set(); }
  });
  const searchRef = useRef(null);

  useEffect(() => {
    try { localStorage.setItem('vulner.pinned', JSON.stringify([...pinned])); } catch { /* ignore */ }
  }, [pinned]);

  useEffect(() => {
    const onKey = (e) => {
      const el = document.activeElement;
      const typing = !!el && /^(INPUT|TEXTAREA)$/.test(el.tagName);
      if (e.altKey && (e.key === 'n' || e.key === 'N')) {
        e.preventDefault();
        onNew();
      } else if (e.key === '/' && !typing) {
        e.preventDefault();
        if (sbHidden) sbToggle();
        if (searchRef.current) searchRef.current.focus();
      } else if (e.key === 'Escape' && el === searchRef.current) {
        setQ('');
        el.blur();
      }
    };
    addEventListener('keydown', onKey);
    return () => removeEventListener('keydown', onKey);
  }, [onNew, sbHidden, sbToggle]);

  const togglePin = (id) => setPinned((prev) => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    return next;
  });

  const term = q.trim().toLowerCase();
  const shown = term ? sessions.filter((s) => String(s.title || 'untitled session').toLowerCase().includes(term)) : sessions;
  const age = (s) => {
    const t = new Date(s.updatedAt).getTime();
    return Number.isNaN(t) ? Infinity : Date.now() - t;
  };
  const DAY = 864e5;
  const groups = [
    ['Pinned', shown.filter((s) => pinned.has(s.id))],
    ['Today', shown.filter((s) => !pinned.has(s.id) && age(s) < DAY)],
    ['Yesterday', shown.filter((s) => !pinned.has(s.id) && age(s) >= DAY && age(s) < 2 * DAY)],
    ['Earlier', shown.filter((s) => !pinned.has(s.id) && age(s) >= 2 * DAY)],
  ].filter((g) => g[1].length);

  const links = [
    ['browser', 'Browser', onBrowser, browserActive, <><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M3 9h18" /></>],
    ['mcp', 'MCP servers', onMcp, mcpActive, <><path d="M9 3v4M15 3v4M7 7h10v4a5 5 0 0 1-10 0zM12 16v5" /></>],
    ['tools', 'Tools', onTools, toolsActive, <><path d="M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18l3 3 6.3-6.3a4 4 0 0 0 5.4-5.4l-2.6 2.6-2.4-.6-.6-2.4z" /></>],
    ['memory', 'Project memory', onMemory, false, <><path d="M3 12a9 9 0 1 0 3-6.7L3 8M3 3v5h5M12 7v5l3 2" /></>],
  ];

  return (
    <aside id="sidebar" className={`sbx${sbHidden ? ' min' : ''}`} style={{ '--sbw': `${sbWidth}px` }} aria-label="Sidebar">
      <div className="sbx-hd">
        <div className="sbx-brand">{sbxAnchor('sbx-brand-anchor')}<span>Oxygen</span></div>
        <button className="sbx-tog" onClick={sbToggle} aria-label={sbHidden ? 'Expand sidebar' : 'Collapse sidebar'} aria-expanded={!sbHidden} title={sbHidden ? 'Expand sidebar' : 'Collapse sidebar'}>
          <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2" /><path d="M9 4v16" /></svg>
        </button>
      </div>

      <div className="sbx-top">
        <button className="sbx-new" onClick={onNew} title="New chat">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg>
          <span className="lbl">New chat</span>
          <kbd>Alt N</kbd>
        </button>
        <label className="sbx-search">
          <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6" /><path d="M20 20l-4-4" /></svg>
          <input ref={searchRef} value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search chats" aria-label="Search chats" autoComplete="off" spellCheck="false" />
          <kbd>/</kbd>
        </label>
      </div>

      <nav className="sbx-nav" aria-label="Workspace">
        {links.map(([key, label, fn, active, glyph]) => (
          <button key={key} className="sbx-link" id={key === 'mcp' ? 'btn-mcp' : key === 'tools' ? 'btn-tools' : undefined} onClick={fn} title={label} aria-current={active ? 'page' : undefined}>
            <SbxIcon>{glyph}</SbxIcon>
            <span className="lbl">{label}</span>
            {sbxAnchor('sbx-anc')}
          </button>
        ))}
      </nav>

      <section className="sbx-chats">
        <div className="sbx-ch-h">
          <span>Chats</span>
          <span className="sbx-count">{sessions.length}</span>
          {sessions.length > 0 && <button className="sbx-clear" onClick={onClear} title="Clear all sessions">Clear</button>}
        </div>
        <div className="sbx-list">
          {bgList.length > 0 && (
            <div>
              <div className="sbx-grp">Background</div>
              <ul className="sbx-ul">
                {bgList.map((t) => (
                  <li key={t.bgId} className="sbx-chat" title={`${t.title} — working in background`}>
                    <span className="sbx-chat-main">
                      <span className="sbx-run" />
                      <span className="sbx-chat-t">{t.title}</span>
                    </span>
                    <span className="sbx-acts">
                      <button onClick={() => onStopBg(t.bgId)} title="Stop this background task" aria-label="Stop this background task">
                        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" /></svg>
                      </button>
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          )}
          {groups.map(([label, items]) => (
            <div key={label}>
              <div className="sbx-grp">{label}</div>
              <ul className="sbx-ul">
                {items.map((s) => (
                  <li key={s.id} className={`sbx-chat${s.id === currentId ? ' on' : ''}`}>
                    <button className="sbx-chat-main" onClick={() => onPick(s.id)} title={s.title || 'Untitled session'}>
                      <span className="sbx-chat-t">{s.title || 'Untitled session'}</span>
                      <span className="sbx-chat-tm">{timeAgo(s.updatedAt)}</span>
                    </button>
                    <span className="sbx-acts">
                      <button className={pinned.has(s.id) ? 'on' : undefined} onClick={() => togglePin(s.id)} title={pinned.has(s.id) ? 'Unpin chat' : 'Pin chat'} aria-label={pinned.has(s.id) ? 'Unpin chat' : 'Pin chat'}>
                        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 17v5M9 3h6l-1 6 3 3v2H7v-2l3-3z" /></svg>
                      </button>
                      <button onClick={() => onDelete(s.id)} title="Delete chat" aria-label="Delete chat">
                        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3" /></svg>
                      </button>
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
          {groups.length === 0 && (
            <div className="sbx-empty">{term ? `No chats match “${q.trim()}”` : 'No chats yet'}</div>
          )}
        </div>
      </section>

      <div className="sbx-ft">
        <SeaWaves />
        <div className="sbx-ft-in">
          <div className="sbx-agent" title="Local agent connected">
            <span className="d" />
            <span className="lbl">Local agent connected</span>
          </div>
          <div className="sbx-me">
            <span className="sbx-av">{initial}</span>
            <span className="sbx-who" title={userEmail}>{userEmail}</span>
            {typeof onSignOut === 'function' && (
              <button className="sbx-out" onClick={onSignOut} title="Sign out" aria-label="Sign out">
                <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 4h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M10 8l-4 4 4 4M6 12h11" /></svg>
              </button>
            )}
          </div>
        </div>
      </div>
      <div className="sb-resizer" onMouseDown={onResizeStart} title="Drag to resize" />
    </aside>
  );
}

// ---------------- mcp panel ----------------

function McpPanel({ open, mcp, onClose, onAction }) {
  const [formOpen, setFormOpen] = useState(false);
  const [fLabel, setFLabel] = useState('');
  const [fCommand, setFCommand] = useState('');
  const [fArgs, setFArgs] = useState('');
  if (!open) return null;
  const mcpList = Array.isArray(mcp) ? mcp : [mcp];

  const renderMcp = (s, idx) => {
    const enabled = !!s?.enabled;
    const connected = !!s?.connected;
    const failed = !!s?.error;
    const target = s?.target;

    let cls = 'off';
    let label = 'disabled';
    if (enabled) {
      if (connected && target === 'ready') { cls = 'on'; label = `connected · ${s.tools} ${s.label} tools`; }
      else if (connected && target === 'down') { cls = 'warn'; label = 'bridge up, target not detected'; }
      else if (connected) { cls = 'warn'; label = 'bridge up, target not confirmed'; }
      else if (failed) { cls = 'off'; label = 'connection failed'; }
      else { cls = 'loading'; label = 'connecting…'; }
    }

    return (
      <div key={s.label} className={`srv-row ${cls}`} style={{ '--i': idx }}>
        <div className="srv-top">
          <span className="srv-dot" />
          <span className="srv-name">{s.name || s.label}</span>
          <span className="srv-state">{label}</span>
          {!enabled ? (
            <button className="srv-act" onClick={() => onAction('enable', { label: s.label })}>Enable</button>
          ) : connected ? (
            <button className="srv-act quiet" onClick={() => onAction('disable', { label: s.label })}>Disable</button>
          ) : failed ? (
            <button className="srv-act" onClick={() => onAction('retry', { label: s.label })}>Retry</button>
          ) : (
            <button className="srv-act quiet" disabled>…</button>
          )}
          {s.label !== 'mcp' && s.label !== 'ida' && s.label !== 'ghidra' && s.label !== 'roblox' && (
            <button className="srv-del" onClick={() => onAction('remove_custom', { label: s.label })} title="Remove custom MCP">×</button>
          )}
        </div>
        {enabled && failed && <div className="mcp-error" title={s.error}>{s.error}</div>}
        {enabled && connected && s.names && s.names.length > 0 && (
          <div className="mcp-tool-list srv-tools">
            {s.names.map((n) => <span key={n} className="mcp-tool">{n}</span>)}
          </div>
        )}
      </div>
    );
  };

  const live = mcpList.filter((s) => s && s.enabled && s.connected).length;
  const submitForm = () => {
    const label = fLabel.trim();
    if (!label || !fCommand.trim()) return;
    onAction('add_custom', { data: { label, command: fCommand.trim(), args: fArgs.split(' ').filter(Boolean) } });
    setFormOpen(false); setFLabel(''); setFCommand(''); setFArgs('');
  };
  return (
    <div className="modal-overlay panel-overlay" onClick={onClose}>
      <aside id="mcp-panel" className="panel mcp open sheet" role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
        <div className="sheet-head">
          <span className="sheet-glyph">
            <Icon name="plugs" size={18} />
          </span>
          <div className="sheet-titles">
            <div className="sheet-title">MCP servers</div>
            <div className="sheet-sub"><TypeText text={`${live} of ${mcpList.length} connected · local bridges the agent can call`} /></div>
          </div>
          <button className="sheet-x" title="Close" onClick={onClose}>
            <Icon name="x" size={13} />
          </button>
        </div>

        <div className="sheet-body">
          <div className="sheet-label">servers <span>{mcpList.length}</span></div>
          <div className="srv-list">{mcpList.map((s, i) => renderMcp(s, i))}</div>

          {!formOpen && (
            <button className="srv-add" onClick={() => setFormOpen(true)}>
              <Icon name="plus" size={15} />
              Add custom server
            </button>
          )}
          {formOpen && (
            <div className="mcp-form">
              <input value={fLabel} onChange={(e) => setFLabel(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))} placeholder="Server name, e.g. brave-search" aria-label="Server name" autoFocus onKeyDown={(e) => { if (e.key === 'Enter') submitForm(); }} />
              <input value={fCommand} onChange={(e) => setFCommand(e.target.value)} placeholder="Command, e.g. npx, python, node" aria-label="Command" onKeyDown={(e) => { if (e.key === 'Enter') submitForm(); }} />
              <input value={fArgs} onChange={(e) => setFArgs(e.target.value)} placeholder="Arguments (optional), space separated" aria-label="Arguments" onKeyDown={(e) => { if (e.key === 'Enter') submitForm(); }} />
              <div className="mcp-form-acts">
                <button className="srv-act" onClick={() => setFormOpen(false)}>Cancel</button>
                <button className="srv-act solid" disabled={!fLabel.trim() || !fCommand.trim()} onClick={submitForm}>Add</button>
              </div>
            </div>
          )}
        </div>

        <p className="sheet-note">Model Context Protocol plugs outside tools into the chat — debuggers, search, filesystem. Only enabled servers get loaded into the prompt.</p>
      </aside>
    </div>
  );
}

