function ToolsPanel({ open, onClose }) {
  const [q, setQ] = useState('');
  const [shut, setShut] = useState(() => new Set());
  const [fade, setFade] = useState(() => new Set());
  const [gone, setGone] = useState(() => new Set());
  const [toastMsg, setToastMsg] = useState('');
  const toastT = useRef(0);
  const wasShown = useRef({});
  useEffect(() => {
    if (!open) return undefined;
    setQ('');
    setShut(new Set());
    return undefined;
  }, [open]);
  useEffect(() => {
    if (!open) return undefined;
    const t = q.trim().toLowerCase();
    const fading = new Set();
    const goneNext = new Set();
    TOOL_REF.forEach((g) => {
      const hit = !t || g.tools.some(([n, d]) => n.includes(t) || d.toLowerCase().includes(t) || g.cat.toLowerCase().includes(t));
      if (!hit) { fading.add(g.cat); goneNext.add(g.cat); }
    });
    setFade(fading);
    const tid = setTimeout(() => {
      setGone(goneNext);
      setFade((f) => { const n = new Set(f); goneNext.forEach((c) => n.delete(c)); return n; });
    }, t ? 280 : 0);
    return () => clearTimeout(tid);
  }, [q, open]);
  if (!open) return null;
  const term = q.trim().toLowerCase();
  const total = TOOL_REF.reduce((n, g) => n + g.tools.length, 0);
  const matches = TOOL_REF.map((g) => (term ? g.tools.filter(([n, d]) => n.includes(term) || d.toLowerCase().includes(term) || g.cat.toLowerCase().includes(term)) : g.tools));
  const shownTotal = matches.reduce((n, m) => n + m.length, 0);
  const sub = term ? shownTotal + ' of ' + total + ' tools match' : total + ' tools \u00b7 ' + TOOL_REF.length + ' groups \u00b7 called automatically from chat';
  const was = wasShown.current;
  let k = 0;
  const hlHtml = (s) => {
    const e = escHtml(s);
    if (!term) return e;
    const i = s.toLowerCase().indexOf(term);
    if (i < 0) return e;
    return escHtml(s.slice(0, i)) + '<mark>' + escHtml(s.slice(i, i + term.length)) + '</mark>' + escHtml(s.slice(i + term.length));
  };
  const copyName = (name) => {
    try { navigator.clipboard.writeText(name); } catch { /* ignore */ }
    setToastMsg('Copied ' + name);
    clearTimeout(toastT.current);
    toastT.current = setTimeout(() => setToastMsg(''), 1400);
  };
  const toggleShut = (cat) => setShut((s) => { const n = new Set(s); if (n.has(cat)) n.delete(cat); else n.add(cat); return n; });

  return (
    <div className="modal-overlay panel-overlay" onClick={onClose}>
      <aside id="tools-panel" className="panel open sheet" role="dialog" aria-modal="true" aria-label="Tools" onClick={(e) => e.stopPropagation()} onKeyDown={(e) => { if (e.key === 'Escape') { if (q) setQ(''); else onClose(); } }}>
        <div className="sheet-head">
          <span className="sheet-glyph">
            <Icon name="wrench" size={18} />
          </span>
          <div className="sheet-titles">
            <div className="sheet-title">Tools</div>
            <div className="sheet-sub"><TypeText text={sub} /></div>
          </div>
          <button type="button" className="sheet-x" title="Close" onClick={onClose}>
            <Icon name="x" size={13} />
          </button>
        </div>

        <div className="sheet-search">
          <label className="search-pill">
            <Icon name="search" size={18} />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Filter by name or what it does" spellCheck="false" autoComplete="off" autoFocus />
            {q ? <button type="button" className="search-clr" title="Clear" onClick={() => setQ('')}><Icon name="x" size={13} /></button> : <kbd>/</kbd>}
          </label>
        </div>

        <div className="sheet-body tools-body">
          {TOOL_REF.map((g, gi) => {
            const mset = new Set(matches[gi].map((t) => t[0]));
            const fading = fade.has(g.cat);
            if (gone.has(g.cat) && !fading) return null;
            const closed = term ? false : shut.has(g.cat);
            return (
              <section key={g.cat + (!fading ? '-in' : '')} className={`tgroup${closed ? ' shut' : ''}${fading ? ' fade' : ''}`} style={{ '--gi': gi }}>
                <button type="button" className="tgh" aria-expanded={!closed} onClick={() => { if (!term) toggleShut(g.cat); }}>
                  <span>{g.cat}</span>
                  <span className="tgh-count">{term ? matches[gi].length + '/' + g.tools.length : g.tools.length}</span>
                  <svg className="tgh-chev" viewBox="0 0 24 24"><path d="M6 9l6 6 6-6" /></svg>
                </button>
                <div className="ttools"><ul>
                  {g.tools.map(([name, desc]) => {
                    const key = gi + ':' + name;
                    const shown = mset.has(name);
                    const delay = shown && was[key] === false ? (k++ * 24) + 'ms' : '0ms';
                    was[key] = shown;
                    return (
                      <li key={name} className={shown ? undefined : 'hide'} style={{ '--d': shown ? delay : '0ms' }}>
                        <div className="tin">
                          <button type="button" className="tl" title="Copy name" onClick={() => shown && copyName(name)}>
                            <b dangerouslySetInnerHTML={{ __html: hlHtml(name) }} />
                            <span dangerouslySetInnerHTML={{ __html: hlHtml(desc) }} />
                          </button>
                        </div>
                      </li>
                    );
                  })}
                </ul></div>
              </section>
            );
          })}
          {!shownTotal && <div className="tools-none"><TypeText text={'No tools match \u201c' + q.trim() + '\u201d'} /></div>}
        </div>
        <div className={'tools-toast' + (toastMsg ? ' on' : '')} role="status">{toastMsg}</div>
      </aside>
    </div>
  );
}

