// ---------------- project memory panel ----------------

function MemPanel({ open, onClose }) {
  const [mem, setMem] = useState('');
  const [path, setPath] = useState('');
  const [saved, setSaved] = useState(false);
  const [err, setErr] = useState('');
  const [confirming, setConfirming] = useState(false);
  const [shake, setShake] = useState(false);
  const baseRef = useRef('');
  const taRef = useRef(null);
  const dirty = open && mem !== baseRef.current;

  const doSave = async () => {
    const r = await V.memSave(mem);
    if (r && r.ok) { baseRef.current = mem; setSaved(true); setTimeout(() => setSaved(false), 1800); }
    else setErr((r && r.error) || 'save failed');
  };

  const tryClose = () => {
    if (dirty && !confirming) {
      setConfirming(true); setShake(true);
      setTimeout(() => setShake(false), 450);
    } else onClose();
  };

  useEffect(() => {
    if (!open) return;
    setSaved(false); setErr(''); setConfirming(false); setShake(false);
    V.memRead().then((r) => {
      const m = r && r.ok ? (r.memory || '') : '';
      baseRef.current = m;
      setMem(m); setPath(r && r.path || '');
      if (!(r && r.ok)) setErr((r && r.error) || 'no project folder open');
    }).catch(() => setErr('no project folder open'));
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') { e.preventDefault(); doSave(); }
      else if (e.key === 'Escape') tryClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, mem, confirming]);

  if (!open) return null;

  const addChip = (h) => {
    setMem((v) => v + (v && !v.endsWith('\n') ? '\n\n' : v ? '\n' : '') + '## ' + h + '\n');
    if (taRef.current) { taRef.current.focus(); taRef.current.scrollTop = taRef.current.scrollHeight; }
  };

  return (
    <div className="modal-overlay panel-overlay" onClick={tryClose}>
      <aside id="mem-panel" className={`panel open sheet${shake ? ' mem-shake' : ''}`} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
        <div className="sheet-head">
          <span className="sheet-glyph">
            <Icon name="clock" size={18} />
          </span>
          <div className="sheet-titles">
            <div className="sheet-title">Project memory</div>
            <div className="sheet-sub"><TypeText text={path ? '.vulner/MEMORY.md · kept across sessions' : 'no project open'} /></div>
          </div>
          <button className="sheet-x" title="Close" onClick={tryClose}>
            <Icon name="x" size={13} />
          </button>
        </div>
        <div className="sheet-body mem-body">
          {err ? <div className="mem-err">{err}</div> : (
            <>
              <div className="sheet-label">
                loaded before every session <span>{(mem || '').length.toLocaleString('en-US')} chars</span>
              </div>
              <div className="mem-chips">
                {['Arch', 'Commands', 'Conventions', 'Findings'].map((h) => (
                  <button key={h} className="mem-chip" onClick={() => addChip(h)}>
                    <Icon name="plus" size={12} />{h}
                  </button>
                ))}
              </div>
              <div className="mem-editor">
                <textarea ref={taRef} className="mem-edit" value={mem} onChange={(e) => setMem(e.target.value)} spellCheck="false" placeholder="# Project memory — arch, commands, conventions, findings…" />
              </div>
              <div className="mem-foot">
                {confirming ? (
                  <>
                    <span className="mem-stat">Discard unsaved changes?</span>
                    <div className="mem-acts">
                      <button className="mem-btn" onClick={() => setConfirming(false)}>Keep editing</button>
                      <button className="mem-btn dark" onClick={() => { setMem(baseRef.current); setConfirming(false); onClose(); }}>Discard</button>
                    </div>
                  </>
                ) : (
                  <>
                    <span className={`mem-stat${dirty ? ' dirty' : saved ? ' ok' : ''}`}>{dirty ? 'Unsaved changes' : saved ? 'Saved' : ''}</span>
                    <div className="mem-acts">
                      <button className="mem-btn dark" disabled={!dirty} onClick={doSave}>Save</button>
                    </div>
                  </>
                )}
              </div>
            </>
          )}
        </div>
      </aside>
    </div>
  );
}

// ---------------- confirm modal ----------------

function ConfirmModal({ open, onCancel, onConfirm }) {
  const [ok, setOk] = useState(false);
  useEffect(() => { if (open) setOk(false); }, [open]);
  if (!open) return null;
  return (
    <div id="confirm" className="modal" onClick={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="modal-card confirm-card">
        <div className="cm-head">
          <svg className="cm-warn" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
            <line x1="12" y1="9" x2="12" y2="13" />
            <line x1="12" y1="17" x2="12.01" y2="17" />
          </svg>
          <span className="cm-title">Delete all chats?</span>
        </div>
        <div className="cm-body">This permanently removes every saved session from this device. Current chat stays open. There is no undo.</div>
        <button type="button" className={`cm-check${ok ? ' cm-check-on' : ''}`} onClick={() => setOk(!ok)}>
          <span className="cm-box">
            {ok && <svg viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12.5 9.5 18 20 6.5" /></svg>}
          </span>
          I understand the risk and want to continue
        </button>
        <div className="modal-actions">
          <button className="btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="btn-danger" disabled={!ok} onClick={onConfirm}>Delete all</button>
        </div>
      </div>
    </div>
  );
}

