  const map = { js: '#f0d27a', jsx: '#7dd3fc', ts: '#7dd3fc', tsx: '#7dd3fc', json: '#a8c3ff', py: '#8ee6a0', css: '#c9a6ff', html: '#ff9e64', md: '#b0b0b8', txt: '#b0b0b8' };
