function SignIn() {
  const Failed = new URLSearchParams(location.search).get('auth') === 'failed';
  const TxtRef = useRef(null);
  useEffect(() => {
    const Txt = TxtRef.current;
    if (!Txt) return;
    const Reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const Ease = 'cubic-bezier(.2,.75,.2,1)';
    let Index = 0, Timer = 0, Disposed = false, Running = [];
    const Next = () => {
      if (Disposed) return;
      Txt.textContent = SignInFacts[Index];
      if (Reduce) {
        Timer = setTimeout(() => { Index = (Index + 1) % SignInFacts.length; Next(); }, 6000);
        return;
      }
      const In = Txt.animate([
        { opacity: 0, filter: 'blur(16px)', transform: 'translateY(12px)', letterSpacing: '.08em' },
        { opacity: 1, filter: 'blur(0)', transform: 'none', letterSpacing: 'inherit' },
      ], { duration: 1200, easing: Ease, fill: 'both' });
      Running = [In];
      In.finished.then(() => {
        if (Disposed) return;
        Timer = setTimeout(() => {
          if (Disposed) return;
          const Out = Txt.animate([
            { opacity: 1, filter: 'blur(0)', transform: 'none' },
            { opacity: 0, filter: 'blur(14px)', transform: 'translateY(-10px)' },
          ], { duration: 900, easing: 'ease-in', fill: 'both' });
          Running.push(Out);
          Out.finished.then(() => {
            if (Disposed) return;
            Running.forEach(A => A.cancel());
            Running = [];
            Index = (Index + 1) % SignInFacts.length;
            Next();
          }).catch(() => {});
        }, 3400);
      }).catch(() => {});
    };
    Next();
    return () => { Disposed = true; clearTimeout(Timer); Running.forEach(A => A.cancel()); };
  }, []);
  const CurRef = useRef(null), PingRef = useRef(null);
  useEffect(() => {
    const Cur = CurRef.current, Ping = PingRef.current;
    if (!Cur || !Ping) return;
    if (!matchMedia('(hover:hover) and (pointer:fine)').matches) return;
    let Cx = -100, Cy = -100, Tx = -100, Ty = -100, Down = false, Link = false, Seen = false, Alive = true, PingT0 = -1e9, PingX = 0, PingY = 0, Last = performance.now();
    const Move = (E) => { Tx = E.clientX; Ty = E.clientY; if (!Seen) { Cx = Tx; Cy = Ty; Seen = true; } Link = !!(E.target.closest && E.target.closest('a')); };
    const DownH = (E) => { Down = true; PingX = E.clientX; PingY = E.clientY; PingT0 = performance.now(); };
    const UpH = () => { Down = false; };
    addEventListener('pointermove', Move);
    addEventListener('pointerdown', DownH);
    addEventListener('pointerup', UpH);
    const Tick = (Now) => {
      if (!Alive) return;
      const Dt = Math.min(.05, (Now - Last) / 1000); Last = Now;
      const F = 1 - Math.exp(-Dt * 22);
      Cx += (Tx - Cx) * F; Cy += (Ty - Cy) * F;
      Cur.style.transform = `translate(${Cx}px,${Cy}px) scale(${Down ? .7 : Link ? 1.35 : 1})`;
      const K = Math.min(1, Math.max(0, (Now - PingT0) / 650));
      const Eased = 1 - Math.pow(1 - K, 3);
      Ping.style.transform = `translate(${PingX}px,${PingY}px) scale(${1 + Eased * 1.9})`;
      Ping.style.opacity = K >= 1 ? 0 : 1 - K;
      requestAnimationFrame(Tick);
    };
    requestAnimationFrame(Tick);
    return () => { Alive = false; removeEventListener('pointermove', Move); removeEventListener('pointerdown', DownH); removeEventListener('pointerup', UpH); };
  }, []);
  const Words = SignInLede.split(/\s+/);
  return (
    <div className="signin">
      <section className="signin-card">
        <h1 className="signin-h1">Welcome <em>back.</em></h1>
        <p className="signin-lede">
          {Words.map((W, N) => (
            <React.Fragment key={N}>
              <span className={N >= Words.length - 2 ? 'hl' : undefined} style={{ animationDelay: `${0.35 + N * 0.07}s` }}>{W}</span>
              {N < Words.length - 1 ? ' ' : null}
            </React.Fragment>
          ))}
        </p>
        <a className="signin-discord" href="/auth/discord">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.317 4.3698a19.7913 19.7913 0 00-4.8851-1.5152.0741.0741 0 00-.0785.0371c-.211.3753-.4447.8648-.6083 1.2495-1.8447-.2762-3.68-.2762-5.4868 0-.1636-.3933-.4058-.8742-.6177-1.2495a.077.077 0 00-.0785-.037 19.7363 19.7363 0 00-4.8852 1.515.0699.0699 0 00-.0321.0277C.5334 9.0458-.319 13.5799.0992 18.0578a.0824.0824 0 00.0312.0561c2.0528 1.5076 4.0413 2.4228 5.9929 3.0294a.0777.0777 0 00.0842-.0276c.4616-.6304.8731-1.2952 1.226-1.9942a.076.076 0 00-.0416-.1057c-.6528-.2476-1.2743-.5495-1.8722-.8923a.077.077 0 01-.0076-.1277c.1258-.0943.2517-.1923.3718-.2914a.0743.0743 0 01.0776-.0105c3.9278 1.7933 8.18 1.7933 12.0614 0a.0739.0739 0 01.0785.0095c.1202.099.246.1981.3728.2924a.077.077 0 01-.0066.1276 12.2986 12.2986 0 01-1.873.8914.0766.0766 0 00-.0407.1067c.3604.698.7719 1.3628 1.225 1.9932a.076.076 0 00.0842.0286c1.961-.6067 3.9495-1.5219 6.0023-3.0294a.077.077 0 00.0313-.0552c.5004-5.177-.8382-9.6739-3.5485-13.6604a.061.061 0 00-.0312-.0286zM8.02 15.3312c-1.1825 0-2.1569-1.0857-2.1569-2.419 0-1.3332.9555-2.4189 2.157-2.4189 1.2108 0 2.1757 1.0952 2.1568 2.419 0 1.3332-.9555 2.4189-2.1569 2.4189zm7.9748 0c-1.1825 0-2.1569-1.0857-2.1569-2.419 0-1.3332.9554-2.4189 2.1569-2.4189 1.2108 0 2.1757 1.0952 2.1568 2.419 0 1.3332-.946 2.4189-2.1568 2.4189z" /></svg>
          Continue with Discord
        </a>
        <p className="signin-fine">By continuing you agree to our <a href="#">Terms</a> and <a href="#">Privacy Policy</a>.</p>
        {Failed && <p className="signin-err">sign-in did not complete, try again</p>}
      </section>
      <div className="signin-facts" aria-live="off">
        <div className="signin-txt" ref={TxtRef} />
      </div>
      <div className="signin-ping" ref={PingRef} />
      <div className="signin-cur" ref={CurRef} />
    </div>
  );
}

function AuthGate() {
  const [Auth, SetAuth] = useState(IS_WEB ? null : { authed: true, user: null });
  useEffect(() => {
    if (!IS_WEB) return;
    let Alive = true;
    fetch('/auth/me', { credentials: 'same-origin' })
      .then((R) => R.json())
      .then((J) => { if (Alive) SetAuth(J); })
      .catch(() => { if (Alive) SetAuth({ authed: true, user: null }); });
    return () => { Alive = false; };
  }, []);
  if (!Auth) return <div className="signin"><div className="signin-box signin-boot">loading oxygen…</div></div>;
  if (!Auth.authed) return <SignIn />;
  return (
    <App
      session={{
        userId: (Auth.user && Auth.user.id) || 'local',
        email: (Auth.user && Auth.user.name) || 'local',
      }}
      onSignOut={IS_WEB ? () => { location.href = '/auth/logout'; } : null}
    />
  );
}

