const ANSI_BASE = {
  30: '#6b6353', 31: '#a3231b', 32: '#2f6b3f', 33: '#8a5a2b', 34: '#2f5a8a', 35: '#6b3f8f', 36: '#2f6f74', 37: '#201c15',
  90: '#8a8069', 91: '#c0392b', 92: '#3f7d4e', 93: '#a3701f', 94: '#3a6ea5', 95: '#7b4fa0', 96: '#3a7d84', 97: '#16130e',
};

function ansi256(n) {
  if (n < 16) return ANSI_BASE[n < 8 ? 30 + n : 90 + (n - 8)] || null;
  if (n >= 232) { const v = 8 + (n - 232) * 10; return `rgb(${v},${v},${v})`; }
  const i = n - 16;
  const r = Math.floor(i / 36), g = Math.floor((i % 36) / 6), b = i % 6;
  const c = (x) => (x ? x * 40 + 55 : 0);
  return `rgb(${c(r)},${c(g)},${c(b)})`;
}

function ansiTokens(text) {
  const tokens = [];
  let color = null, bold = false, dim = false, underline = false;
  const re = /\x1b\[([0-9;]*)m/g;
  let last = 0, m;
  const push = (s) => { if (s) tokens.push({ s, color, bold, dim, underline }); };
  while ((m = re.exec(text))) {
    push(text.slice(last, m.index));
    const codes = (m[1] || '0').split(';').map((x) => Number(x) || 0);
    for (let i = 0; i < codes.length; i++) {
      const c = codes[i];
      if (c === 0) { color = null; bold = false; dim = false; underline = false; }
      else if (c === 1) bold = true;
      else if (c === 2) dim = true;
      else if (c === 4) underline = true;
      else if (c === 22) { bold = false; dim = false; }
      else if (c === 24) underline = false;
      else if (c === 39) color = null;
      else if (ANSI_BASE[c]) color = ANSI_BASE[c];
      else if (c === 38 || c === 48) {
        if (codes[i + 1] === 5) { if (c === 38) color = ansi256(codes[i + 2]); i += 2; }
        else if (codes[i + 1] === 2) { if (c === 38) color = `rgb(${codes[i + 2]},${codes[i + 3]},${codes[i + 4]})`; i += 4; }
      }
    }
    last = m.index + m[0].length;
  }
  push(text.slice(last));
  return tokens;
}

function stripAnsiNoise(s) {
  // fuhhh kill cursor/osc junk but keep sgr colors cuhhh :broken_heart:
  return s.replace(/\x1b\][^\x07]*\x07/g, '').replace(/\x1b\[[0-9;?]*[A-LN-Za-ln-z]/g, '');
}

function Terminal({ open, onClose }) {
  const [session, setSession] = useState(null);
  const [lines, setLines] = useState([]);
  const [cwd, setCwd] = useState('');
  const [input, setInput] = useState('');
  const [busy, setBusy] = useState(false);
  const [history, setHistory] = useState([]);
  const [histIdx, setHistIdx] = useState(-1);
  const [height, setHeight] = useState(() => {
    const h = Number(localStorage.getItem('vulner.termH'));
    return h >= 150 && h <= 900 ? h : 320;
  });
  const idRef = useRef(null);
  const pendingRef = useRef({ out: '', err: '' });
  const bodyRef = useRef(null);
  const inputRef = useRef(null);
  const stickRef = useRef(true);
  const refocusRef = useRef(false);

  const pushLines = useCallback((items) => {
    if (!items.length) return;
    setLines((prev) => prev.concat(items).slice(-2500));
  }, []);

  const append = useCallback((chunk, stream) => {
    const clean = stripAnsiNoise(String(chunk || '')).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    const merged = pendingRef.current[stream] + clean;
    const parts = merged.split('\n');
    pendingRef.current[stream] = parts.pop();
    if (parts.length) pushLines(parts.map((t) => ({ k: 'out', t, stream })));
  }, [pushLines]);

  const flush = useCallback(() => {
    const add = [];
    if (pendingRef.current.out) add.push({ k: 'out', t: pendingRef.current.out, stream: 'out' });
    if (pendingRef.current.err) add.push({ k: 'out', t: pendingRef.current.err, stream: 'err' });
    pendingRef.current = { out: '', err: '' };
    pushLines(add);
  }, [pushLines]);

  useEffect(() => {
    if (!open) {
      if (idRef.current) { V.termDispose(idRef.current); idRef.current = null; }
      pendingRef.current = { out: '', err: '' };
      setSession(null); setLines([]); setCwd(''); setInput(''); setBusy(false); setHistIdx(-1);
      return;
    }
    let dead = false;
    V.termStart().then((s) => {
      if (dead || !s || s.error) return;
      idRef.current = s.id;
      setSession(s);
      setCwd(s.cwd);
    });
    const off = V.onTerm((ev) => {
      if (!ev || ev.id !== idRef.current) return;
      if (ev.type === 'clear') { setLines([]); return; }
      if (ev.type === 'closed') { onClose(); return; }
      if (ev.type === 'data') { append(ev.data, ev.stream === 'err' ? 'err' : 'out'); return; }
      if (ev.type === 'done') { flush(); setBusy(false); if (ev.cwd) setCwd(ev.cwd); }
    });
    const t = setTimeout(() => { try { inputRef.current?.focus(); } catch {} }, 60);
    return () => { dead = true; clearTimeout(t); off && off(); };
  }, [open, append, flush, onClose]);

  useEffect(() => {
    const el = bodyRef.current;
    if (el && stickRef.current) el.scrollTop = el.scrollHeight;
  }, [lines, busy]);

  const fmtPath = (p) => {
    const root = session && session.cwd ? session.cwd : '';
    if (!p) return '~';
    if (root && p.toLowerCase() === root.toLowerCase()) return '~';
    if (root && p.toLowerCase().startsWith(root.toLowerCase() + '\\')) {
      return '~\\' + p.slice(root.length + 1);
    }
    return p;
  };

  const run = async () => {
    if (busy || !idRef.current) return;
    const line = input;
    setInput('');
    setHistIdx(-1);
    if (line.trim()) setHistory((h) => h.concat([line]).slice(-200));
    pushLines([{ k: 'cmd', cmd: line, cwd }]);
    stickRef.current = true;
    refocusRef.current = document.activeElement === inputRef.current;
    if (!line.trim()) return;
    setBusy(true);
    const r = await V.termRun(idRef.current, line);
    if (r && r.error) {
      pushLines([{ k: 'out', t: r.error, stream: 'err' }]);
      setBusy(false);
      return;
    }
    if (r && r.cwd) setCwd(r.cwd);
    if (!(r && r.running)) setBusy(false);
  };

  const stop = () => {
    if (busy && idRef.current) {
      V.termKill(idRef.current);
      pushLines([{ k: 'out', t: '^C', stream: 'err' }]);
      setBusy(false);
      return;
    }
    setInput('');
  };

  useEffect(() => {
    if (open && !busy && refocusRef.current) {
      refocusRef.current = false;
      try { inputRef.current?.focus(); } catch {}
    }
  }, [open, busy]);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => {
      if (!(e.ctrlKey || e.metaKey)) return;
      const key = String(e.key || '').toLowerCase();
      if (key === 'c' && busy && !String(window.getSelection() || '').trim()) {
        e.preventDefault();
        stop();
      } else if (key === 'l' && document.activeElement !== inputRef.current) {
        e.preventDefault();
        setLines([]);
      }
    };
    document.addEventListener('keydown', onDoc);
    return () => document.removeEventListener('keydown', onDoc);
  }, [open, busy]);

  const onKeyDown = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); run(); return; }
    if (e.key === 'c' && e.ctrlKey) { e.preventDefault(); stop(); return; }
    if (e.key === 'l' && e.ctrlKey) { e.preventDefault(); setLines([]); return; }
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (!history.length) return;
      const next = Math.min(history.length - 1, histIdx < 0 ? history.length - 1 : histIdx - 1);
      setHistIdx(next);
      setInput(history[next]);
      return;
    }
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (histIdx < 0) return;
      const next = histIdx + 1;
      if (next >= history.length) { setHistIdx(-1); setInput(''); return; }
      setHistIdx(next);
      setInput(history[next]);
    }
  };

  const startResize = (e) => {
    e.preventDefault();
    const startY = e.clientY;
    const startH = height;
    let last = startH;
    const move = (ev) => {
      last = Math.max(150, Math.min(window.innerHeight - 170, startH + (startY - ev.clientY)));
      setHeight(last);
    };
    const up = () => {
      localStorage.setItem('vulner.termH', String(Math.round(last)));
      document.removeEventListener('mousemove', move);
      document.removeEventListener('mouseup', up);
    };
    document.addEventListener('mousemove', move);
    document.addEventListener('mouseup', up);
  };

  const promptBits = (cmd, path) => (
    <>
      <span className="term-user">{session ? session.user : 'user'}</span>
      <span className="term-at">@</span>
      <span className="term-host">{session ? session.host : 'vulner'}</span>
      <span className="term-colon">:</span>
      <span className="term-path">{fmtPath(path)}</span>
      <span className="term-sign">{'>'}</span>
      {cmd !== null && <span className="term-cmd-text"> {cmd}</span>}
    </>
  );

  const promptLine = (cmd, path, key) => (
    <div key={key} className="term-line term-cmd">{promptBits(cmd, path)}</div>
  );

  return (
    <section className={`term-dock${open ? ' open' : ''}`} style={open ? { height } : undefined}>
      <div className="term-grip" onMouseDown={startResize} title="Drag to resize" />
      <header className="term-head">
        <span className="term-dots"><i /><i /><i /></span>
        <span className="term-title">
          {session ? `${session.user}@${session.host}` : 'vulner'} : {fmtPath(cwd)}
        </span>
        <span className={`term-state${busy ? ' busy' : ''}`}>{busy ? 'running' : 'idle'}</span>
        <button className="term-x" title="Close terminal" onClick={onClose}>
          <Icon name="x" size={10} />
        </button>
      </header>
      <div
        className="term-body"
        ref={bodyRef}
        onScroll={(e) => {
          const el = e.currentTarget;
          stickRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40;
        }}
        onClick={() => { try { inputRef.current?.focus(); } catch {} }}
      >
        {lines.map((ln, i) => (
          ln.k === 'cmd'
            ? promptLine(ln.cmd, ln.cwd, `c${i}`)
            : (
              <div key={`o${i}`} className={`term-line term-out${ln.stream === 'err' ? ' err' : ''}`}>
                {ansiTokens(ln.t).map((tk, j) => (
                  <span
                    key={j}
                    style={{
                      color: tk.color || undefined,
                      fontWeight: tk.bold ? 700 : undefined,
                      opacity: tk.dim ? 0.72 : undefined,
                      textDecoration: tk.underline ? 'underline' : undefined,
                    }}
                  >{tk.s}</span>
                ))}
              </div>
            )
        ))}
        {!busy && (
          <div className="term-line term-live">
            {promptBits(null, cwd)}
            <input
              ref={inputRef}
              className="term-input"
              value={input}
              spellCheck={false}
              autoComplete="off"
              autoCorrect="off"
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={onKeyDown}
              aria-label="Terminal input"
            />
          </div>
        )}
      </div>
    </section>
  );
}

function App({ session, onSignOut }) {
  const [items, setItems] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [streaming, setStreaming] = useState(false);
  const [pendingImg, setPendingImg] = useState(null);
  const [bgList, setBgList] = useState([]);
  const [memOpen, setMemOpen] = useState(false);
  const [gate, setGate] = useState({ shown: true, phase: 'boot' });
  const gateWasDown = useRef(false);
  const gateTimers = useRef([]);
  useEffect(() => {
    V.gateState().then((g) => {
      if (!g || typeof g.down !== 'boolean') return;
      if (g.down) { gateWasDown.current = true; setGate({ shown: true, phase: 'down' }); }
      else { setGate({ shown: true, phase: 'fade' }); gateTimers.current = [setTimeout(() => setGate({ shown: false, phase: 'boot' }), 900)]; }
    }).catch(() => {});
  }, []);

  const [canContinue, setCanContinue] = useState(false);
  const [sessions, setSessions] = useState([]);
  const [mcp, setMcp] = useState([]);
  const [title, setTitle] = useState('New session');
  const [currentId, setCurrentId] = useState(null);
  const [mcpOpen, setMcpOpen] = useState(false);
  const [addMcpOpen, setAddMcpOpen] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [input, setInput] = useState('');
  const [ideLog, setIdeLog] = useState([]);
  const [usageLocked, setUsageLocked] = useState(false);
  const [toolsOpen, setToolsOpen] = useState(false);
  const [currentModel, setCurrentModel] = useState(null);
  const [ideChangeTrigger, setIdeChangeTrigger] = useState(0);
  const [roots, setRoots] = useState([]);
  const [ideOpenRequest, setIdeOpenRequest] = useState(null);
  const [ideOpen, setIdeOpen] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [termOpen, setTermOpen] = useState(false);
  const [heroIdx, setHeroIdx] = useState(0);
  const [heroPhase, setHeroPhase] = useState('in');

  const [isFocused, setIsFocused] = useState(false);
  const [sbWidth, setSbWidth] = useState(() => { const w = Number(localStorage.getItem('vulner.sbW')); return w >= 224 && w <= 360 ? w : 248; });
  const [sbHidden, setSbHidden] = useState(false);
  const [sbDrag, setSbDrag] = useState(false);

  const threadRef = useRef(null);
  const inputRef = useRef(null);
  const itemsRef = useRef(items);
  itemsRef.current = items;
  const currentIdRef = useRef(currentId);
  currentIdRef.current = currentId;
  const sessionRef = useRef(null);
  const resetRef = useRef(false);

  const startResize = (e) => {
    e.preventDefault();
    setSbDrag(true);
    const move = (ev) => setSbWidth(Math.max(234, Math.min(368, ev.clientX)));
    const up = () => { setSbDrag(false); localStorage.setItem('vulner.sbW', String(sbRef.current)); document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); };
    document.addEventListener('mousemove', move);
    document.addEventListener('mouseup', up);
  };
  const sbRef = useRef(sbWidth);
  useEffect(() => { sbRef.current = sbWidth; }, [sbWidth]);
  useEffect(() => {
    if (!streaming) return;
    const onKey = (e) => {
      const t = e.target || {};
      const tag = (t.tagName || '').toUpperCase();
      const typing = tag === 'TEXTAREA' || tag === 'INPUT' || t.isContentEditable;
      const typed = (inputRef.current && inputRef.current.value) || '';
      if (e.code === 'Space' && !typing && !typed.trim()) { e.preventDefault(); V.stop(); }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [streaming]);

  useEffect(() => {
    // gamso workspace pane retired, chat only son :sob:
  }, [items.length]);

  const bump = useCallback(() => setItems([...itemsRef.current]), []);

  const pushLog = useCallback((kind, text) => {
    setIdeLog((l) => [...l.slice(-199), { t: nowStamp(), kind, text }]);
  }, []);

  const scrollBottom = () => {
    requestAnimationFrame(() => { const el = threadRef.current; if (el) el.scrollTop = el.scrollHeight; });
  };

  useEffect(() => { scrollBottom(); }, [items]);

  const refreshSessions = useCallback(async () => {
    const list = await V.listSessions();
    setSessions(list);
  }, []);

  const refreshUsage = useCallback(async () => {
    // No auth/quota layer: the app is always unlimited locally.
    setUsageLocked(false);
  }, []);

  const refreshModel = useCallback(async () => {
    try {
      const r = await V.getModels();
      if (r && r.current) setCurrentModel(r.current);
    } catch {}
  }, []);

  const loadMcp = useCallback(async () => {
    try { setMcp(await V.getMcp()); } catch { setMcp([{ connected: false, tools: 0, names: [], error: 'unavailable', label: 'mcp', name: 'x64dbg', enabled: true, command: '' }]); }
  }, []);

  const actMcp = useCallback(async (action, opts = {}) => {
    if (action === 'add_custom') {
      if (opts.data) {
        setMcp(await V.getMcp({ save_custom: opts.data }));
        return;
      }
      setAddMcpOpen(true);
      return;
    }
    if (action === 'remove_custom') {
      if (confirm(`Remove custom MCP server "${opts.label}"?`)) {
        setMcp(await V.getMcp({ remove_custom: true, label: opts.label }));
      }
      return;
    }
    setMcp((prev) => {
      const list = Array.isArray(prev) ? prev : [prev];
      return list.map(s => s.label === (opts.label || 'mcp') ? { ...s, connected: false, tools: 0, error: null } : s);
    });
    const mcpOpts = { label: opts.label };
    if (action === 'enable') mcpOpts.enable = true;
    else if (action === 'disable') mcpOpts.enable = false;
    else mcpOpts.reconnect = true;
    try { setMcp(await V.getMcp(mcpOpts)); }
    catch { loadMcp(); }
  }, [loadMcp]);

  useEffect(() => {
    V.onEvent((ev) => {
      if (ev.type === 'user') {
        if (sessionRef.current !== null && ev.session && ev.session !== sessionRef.current) return;
        resetRef.current = false;
        if (ev.session) sessionRef.current = ev.session;
        setCurrentId(ev.session);
        setItems((prev) => [...prev, { id: nextId(), kind: 'user', content: ev.content, image: ev.image || null, turn: ev.turn }]);
        
        return;
      }
      if (resetRef.current) {
        if (ev.type === 'turn_end') { setStreaming(false);  refreshSessions(); }
        return;
      }
      if (String(ev.session || '').startsWith('bg-')) return;
      switch (ev.type) {
        case 'gate': {
          gateTimers.current.forEach(clearTimeout);
          if (ev.down) {
            gateWasDown.current = true;
            setGate({ shown: true, phase: 'down' });
          } else if (gateWasDown.current) {
            setGate((g) => (g.shown ? { shown: true, phase: 'up' } : g));
            gateTimers.current = [
              setTimeout(() => setGate({ shown: true, phase: 'out' }), 2400),
              setTimeout(() => setGate({ shown: false, phase: 'boot' }), 3300),
            ];
          } else {
            setGate({ shown: true, phase: 'fade' });
            gateTimers.current = [setTimeout(() => setGate({ shown: false, phase: 'boot' }), 900)];
          }
          break;
        }
        case 'bg_started': {
          setBgList((prev) => prev.some((t) => t.bgId === ev.bgId) ? prev : [...prev, { bgId: ev.bgId, title: ev.title, status: 'running' }]);
          break;
        }
        case 'bg_done': {
          setBgList((prev) => prev.filter((t) => t.bgId !== ev.bgId));
          pushLog('sys', `background task "${ev.title}" finished`);
          break;
        }
        case 'bg_failed': {
          setBgList((prev) => prev.filter((t) => t.bgId !== ev.bgId));
          pushLog('sys', `background task failed: ${ev.message || ev.title}`);
          break;
        }
      }
      if (ev.session && sessionRef.current !== null && ev.session !== sessionRef.current) return;
      if (ev.session) sessionRef.current = ev.session;
      switch (ev.type) {
        case 'turn_start': {
          setCanContinue(false);
          setStreaming(true);
          
          setItems((prev) => [...prev, { id: nextId(), kind: 'assistant', content: '', streaming: true, tools: [], diffs: [], blocks: [{ t: 'text', text: '' }], bump }]);
          break;
        }
        case 'clear_stream': {
          setItems((prev) => {
            const copy = [...prev];
            const last = copy[copy.length - 1];
            if (last && last.kind === 'assistant') {
              const blocks = (last.blocks || []).map((b) => (b.t === 'text' ? { ...b, text: '' } : b));
              copy[copy.length - 1] = { ...last, content: '', blocks };
            }
            return copy;
          });
          break;
        }
        case 'delta': {
          setItems((prev) => {
            const last = prev[prev.length - 1];
            if (!last || last.kind !== 'assistant') return prev;
            const copy = [...prev];
            const blocks = last.blocks ? [...last.blocks] : [];
            const li = blocks.length - 1;
            if (li >= 0 && blocks[li].t === 'text') {
              blocks[li] = { ...blocks[li], text: blocks[li].text + ev.text };
            } else {
              blocks.push({ t: 'text', text: ev.text });
            }
            copy[copy.length - 1] = { ...last, content: last.content + ev.text, blocks };
            return copy;
          });
          break;
        }
        case 'tool_start': {
          
          pushLog('tool', `running ${ev.name} ${ev.args ? JSON.stringify(ev.args).slice(0, 140) : ''}`);
          setItems((prev) => {
            const copy = [...prev];
            const last = copy[copy.length - 1];
            if (last && last.kind === 'assistant') {
              const tool = { id: nextId(), callId: ev.tool_call_id, name: ev.name, args: ev.args, done: false, result: '', open: false };
              copy[copy.length - 1] = { ...last, tools: [...last.tools, tool], blocks: [...(last.blocks || []), { t: 'tool', tool }] };
            }
            return copy;
          });
          break;
        }
        case 'tool_result': {
          setItems((prev) => {
            const copy = [...prev];
            for (let i = copy.length - 1; i >= 0; i--) {
              const it = copy[i];
              if (it.kind === 'assistant') {
                const aborted = !!ev.result?.error && /abort/i.test(String(ev.result.error));
                for (const t of it.tools) {
                  if (((t.callId && ev.tool_call_id && t.callId === ev.tool_call_id) || (!t.callId && t.name === ev.name))) {
                    t.done = true;
                    t.error = !!ev.result?.error && !aborted;
                    t.stopped = aborted;
                    t.ms = ev.result?.ms ?? '';
                    t.result = JSON.stringify(ev.result, null, 2);
                  }
                }
                copy[i] = { ...it };
                break;
              }
            }
            return copy;
          });
          
          if (ev.name === 'task_list' && ev.result && !ev.result.error) {
            setTasks((prev) => {
              const res = ev.result;
              if (res.action === 'add' && Array.isArray(res.tasks)) {
                return res.tasks.map(t => ({ text: t, completed: false }));
              } else if (res.action === 'update' && typeof res.index === 'number') {
                const next = [...prev];
                if (next[res.index]) next[res.index] = { ...next[res.index], completed: !!res.completed };
                return next;
              } else if (res.action === 'clear') {
                return [];
              }
              return prev;
            });
          }

          
          const aborted = !!ev.result?.error && /abort/i.test(String(ev.result.error));
          const errText = ev.result?.error ? `error: ${String(ev.result.error).slice(0, 120)}` : '';
          pushLog(aborted || errText ? 'tool' : 'done', `${ev.name} done ${aborted ? '(stopped)' : ''} ${errText}`.trim());
          break;
        }
        case 'assistant': {
          setCanContinue(false);
          setItems((prev) => {
            const copy = [...prev];
            const last = copy[copy.length - 1];
            if (last && last.kind === 'assistant') {
              const blocks = last.blocks ? [...last.blocks] : [];
              const li = blocks.length - 1;
              if (li >= 0 && blocks[li].t === 'text') {
                const txt = blocks[li].text && blocks[li].text.trim() ? blocks[li].text : (ev.content || '');
                blocks[li] = { ...blocks[li], text: txt };
              } else if (ev.content) {
                blocks.push({ t: 'text', text: ev.content });
              }
              copy[copy.length - 1] = { ...last, content: (last.content && last.content.trim()) ? last.content : (ev.content || ''), blocks, streaming: false, turn: ev.turn ?? last.turn };
            }
            return copy;
          });
          setStreaming(false);
          
          break;
        }
        case 'final': {
          // fuhhh engine sends da CLEANED content here — replace live text even if empty
          // so glued tool junk disappears after every tool turn son :broken_heart:
          setItems((prev) => {
            const copy = [...prev];
            const last = copy[copy.length - 1];
            if (last && last.kind === 'assistant') {
              const blocks = (last.blocks || []).filter((b) => b.t !== 'text');
              if (ev.content && String(ev.content).trim()) blocks.push({ t: 'text', text: String(ev.content) });
              copy[copy.length - 1] = { ...last, content: String(ev.content || ''), blocks, streaming: false, turn: ev.turn ?? last.turn };
            }
            return copy;
          });
          break;
        }
        case 'preview_open': {
          setPreviewOpen(true);
          break;
        }
        case 'error': {
          setItems((prev) => [...prev, { id: nextId(), kind: 'error', content: ev.message }]);
          setCanContinue(true);
          setStreaming(false);
          
          break;
        }
        case 'turn_end': {
          setCanContinue(true);
          setStreaming(false);
          
          setItems((prev) => {
            const copy = prev.map((it) => {
              if (it.kind !== 'assistant') return it;
              const hasRunning = it.tools.some((t) => !t.done);
              if (!hasRunning && !it.streaming) return it;
              for (const t of it.tools) {
                if (!t.done) { t.done = true; t.stopped = true; t.ms = ''; t.result = 'stopped'; }
              }
              return { ...it, streaming: false };
            });
            return copy;
          });
          if (ev.session) {
            setCurrentId(ev.session);
            const firstUser = itemsRef.current.find((i) => i.kind === 'user');
            if (firstUser) setTitle(firstUser.content.slice(0, 60));
          }
          refreshSessions();
          break;
        }
        case 'diff': {
          if (ev.session && currentIdRef.current && ev.session !== currentIdRef.current) break;
          setIdeOpenRequest({ path: ev.file, ts: Date.now() });
          setItems((prev) => {
            const copy = [...prev];
            for (let i = copy.length - 1; i >= 0; i--) {
              const it = copy[i];
              if (it.kind === 'assistant') {
                const diff = { id: nextId(), file: ev.file, added: ev.added, removed: ev.removed, lines: ev.lines };
                copy[i] = { ...it, diffs: [...(it.diffs || []), diff], blocks: [...(it.blocks || []), { t: 'diff', diff }] };
                break;
              }
            }
            return copy;
          });
          break;
        }
        case 'mcp_status': {
          setMcp(ev.status);
          break;
        }
        case 'usage_blocked': {
          setUsageLocked(true);
          setStreaming(false);
          
          break;
        }
        case 'ide:change': {
          setIdeChangeTrigger((t) => t + 1);
          break;
        }
      }
    });
  }, [bump, refreshSessions]);

  useEffect(() => {
    Promise.all([loadMcp(), refreshSessions(), refreshUsage(), refreshModel()]).then(() => inputRef.current?.focus());
  }, [loadMcp, refreshSessions, refreshUsage, refreshModel]);

  useEffect(() => {
    if (!usageLocked) return;
    const t = setInterval(() => refreshUsage(), 30000);
    return () => clearInterval(t);
  }, [usageLocked, refreshUsage]);

  useEffect(() => {
    if (ideChangeTrigger < 0) setIdeChangeTrigger(0);
  }, [ideChangeTrigger]);

  const refreshRoots = useCallback(async () => {
    try { const r = await V.ideRoots(); setRoots((r && Array.isArray(r.roots) ? r.roots : [])); } catch {}
  }, []);

  useEffect(() => { refreshRoots(); }, [ideChangeTrigger, refreshRoots]);

  const openFolder = async () => {
    await V.ideAddFolder();
    setIdeChangeTrigger((o) => o + 1);
  };

  useEffect(() => {
    const onDoc = (e) => {
      if (mcpOpen && !e.target.closest('#mcp-panel') && !e.target.closest('#btn-mcp')) setMcpOpen(false);
      if (toolsOpen && !e.target.closest('#tools-panel') && !e.target.closest('#btn-tools')) setToolsOpen(false);
    };
    const onKey = (e) => {
      if (e.key !== 'Escape') return;
      if (memOpen) { setMemOpen(false); e.stopPropagation(); }
      if (mcpOpen) { setMcpOpen(false); e.stopPropagation(); }
      if (toolsOpen) { setToolsOpen(false); e.stopPropagation(); }
    };
    document.addEventListener('click', onDoc);
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('click', onDoc); document.removeEventListener('keydown', onKey); };
  }, [mcpOpen, toolsOpen, memOpen]);

  const sendPrompt = (text, image) => {
    if (streaming || usageLocked) return;
    if (!text.trim() && !image) return;
    setCanContinue(false);
    V.send(text, image);
    inputRef.current?.focus();
  };

  const handleContinue = async () => {
    if (streaming || usageLocked) return;
    setCanContinue(false);
    // The main process forks this session into a new one; clear the session ref
    // so the fork's 'user' event (which carries the new session id) is accepted
    // and drives the switch. Stale events for the old session are suppressed.
    resetRef.current = true;
    sessionRef.current = null;
    try {
      const res = await V.continue();
      if (res && res.ok === false) throw new Error(res.error || 'Could not continue');
    } catch (e) {
      resetRef.current = false;
      setItems((prev) => [...prev, { id: nextId(), kind: 'error', content: String(e.message || e) }]);
      setCanContinue(true);
      setStreaming(false);
      
    }
    inputRef.current?.focus();
  };

  const pickModel = async (id) => {
    if (streaming || usageLocked) return;
    try { setCurrentModel(await V.setModel(id)); } catch {}
    inputRef.current?.focus();
  };

  const send = () => {
    const text = input.trim();
    if ((!text && !pendingImg) || streaming || usageLocked) return;
    const image = pendingImg;
    setInput('');
    setPendingImg(null);
    sendPrompt(text, image);
  };

  const sendBg = () => {
    const text = input.trim();
    if (!text || streaming) return;
    setInput('');
    const title = text.slice(0, 40);
    V.bgSend(title, text).then((r) => {
      if (!r || !r.ok) pushLog('sys', `background task refused: ${r.error || 'unknown'}`);
    }).catch(() => {});
    inputRef.current?.focus();
  };

  const pickImage = (dataUrl) => {
    setPendingImg(dataUrl);
    inputRef.current?.focus();
  };

  const onPasteImage = async (e) => {
    const cd = e.clipboardData;
    let imgData = null;
    if (cd) {
      const f = Array.from(cd.files || []).find((x) => x.type.startsWith('image/'));
      if (f) imgData = await new Promise((res) => { const r = new FileReader(); r.onload = () => res(r.result); r.readAsDataURL(f); });
      else if ((cd.types || []).includes('image/png')) imgData = null;
    }
    if (!imgData && !cd?.files?.length) {
      try { const r = await V.readImage(); if (r && r.dataUrl) imgData = r.dataUrl; } catch {}
    }
    if (imgData) { e.preventDefault(); pickImage(imgData); return; }
    const text = cd ? cd.getData('text') : '';
    if (!text && cd) { e.preventDefault(); const r = await V.readImage(); if (r && r.dataUrl) pickImage(r.dataUrl); }
  };

  const onDropImage = (e) => {
    const f = Array.from((e.dataTransfer && e.dataTransfer.files) || []).find((x) => x.type.startsWith('image/'));
    if (!f) return;
    e.preventDefault();
    const r = new FileReader();
    r.onload = () => pickImage(r.result);
    r.readAsDataURL(f);
  };

  const EXAMPLES = [
    { title: 'Reverse Engineering', text: 'Reverse this website for me', icon: 'globe', color: '#2f5a8a' },
    { title: 'Deobfuscation', text: 'Analyze and deobfuscate the scripts in the current folder', icon: 'play', color: '#8a5a2b' },
    { title: 'Security Audit', text: 'Audit the binary files in my project for potential vulnerabilities', icon: 'cpu', color: '#8a5a2b' },
    { title: 'Exploit Dev', text: 'Help me write a custom exploit PoC for a buffer overflow', icon: 'terminal', color: '#2f6f74' },
  ];

  const newChat = async () => {
    V.stop();
    resetRef.current = true;
    await V.newChat();
    sessionRef.current = null;
    setItems([]);
    setTasks([]);
    setIdeLog([]);
    setTitle('New session');
    setCurrentId(null);
    setCanContinue(false);
    inputRef.current?.focus();
  };

  const loadConversation = (restored) => {
    if (!restored || !restored.messages) return false;
    setCanContinue(false);
    const list = [];
    const pending = new Map();
    let turn = 0;
    for (const m of restored.messages) {
      if (m.role === 'user') {
        turn = typeof m._turn === 'number' && m._turn > 0 ? m._turn : turn + 1;
        const parts = Array.isArray(m.content) ? m.content.filter((p) => p && p.type === 'text').map((p) => p.text).join('\n') : m.content;
        const img = Array.isArray(m.content) ? ((m.content.find((p) => p && p.type === 'image_url') || {}).image_url || {}).url || null : null;
        list.push({ id: nextId(), kind: 'user', content: parts, image: img, turn });
      } else if (m.role === 'assistant') {
        if (!m.content && !(m.tool_calls && m.tool_calls.length)) continue;
        const lastItem = list[list.length - 1];
        const blocks = m.content ? [{ t: 'text', text: m.content }] : [];
        const item = { id: nextId(), kind: 'assistant', content: m.content || '', streaming: false, tools: [], diffs: [], blocks, bump, turn };
        const target = lastItem && lastItem.kind === 'assistant' ? lastItem : (list.push(item), item);
        if (target !== item && m.content) {
          target.content = target.content ? `${target.content}\n\n${m.content}` : m.content;
          target.blocks.push({ t: 'text', text: m.content });
        }
        if (m.tool_calls && m.tool_calls.length) {
          for (const tc of m.tool_calls) {
            const tool = {
              id: nextId(), callId: tc.id, name: tc.function?.name || '?',
              args: tc.function?.arguments || '{}', done: false, error: false, result: '', open: false,
            };
            target.tools.push(tool);
            target.blocks.push({ t: 'tool', tool });
            pending.set(tc.id, tool);
          }
        }
      } else if (m.role === 'tool' && pending.has(m.tool_call_id)) {
        const tool = pending.get(m.tool_call_id);
        let parsed = null;
        try { parsed = JSON.parse(m.content); } catch {}
        tool.done = true;
        if (parsed && typeof parsed === 'object') {
          tool.ms = parsed.ms ?? '';
          tool.error = !!parsed.error;
          tool.result = JSON.stringify(parsed, null, 2);
        } else {
          tool.result = m.content;
        }
      }
    }
    setItems(list);
    
    // Reconstruct tasks from history
    let lastTasks = [];
    for (const item of list) {
      if (item.kind === 'assistant') {
        for (const tool of item.tools) {
          if (tool.name === 'task_list' && tool.done && tool.result) {
            try {
              const res = JSON.parse(tool.result);
              if (res.action === 'add' && Array.isArray(res.tasks)) {
                lastTasks = res.tasks.map(t => ({ text: t, completed: false }));
              } else if (res.action === 'update' && typeof res.index === 'number') {
                if (lastTasks[res.index]) lastTasks[res.index].completed = !!res.completed;
              } else if (res.action === 'clear') {
                lastTasks = [];
              }
            } catch {}
          }
        }
      }
    }
    setTasks(lastTasks);

    setCurrentId(restored.id);
    sessionRef.current = restored.id;
    setTitle(restored.title || 'Untitled session');
    return true;
  };

  const pickSession = async (id) => {
    const restored = await V.restoreSession(id);
    if (!restored) return;
    loadConversation(restored);
  };

  const handleRestore = async (item) => {
    if (!currentIdRef.current || !item.turn) return;
    const mode = item.kind === 'user' ? 'start' : 'end';
    if (!confirm(`Restore to this point? This reverts file changes and removes all later messages.`)) return;
    const res = await V.restorePoint(currentIdRef.current, item.turn, mode);
    if (res) loadConversation(res);
  };

  const handleRetry = async (item) => {
    if (streaming || usageLocked || !currentIdRef.current || !item.turn) return;
    let idx = items.findIndex((it) => it.id === item.id);
    while (idx >= 0 && items[idx].kind !== 'user') idx--;
    if (idx < 0) return;
    const text = items[idx].content;
    const res = await V.restorePoint(currentIdRef.current, item.turn, 'start');
    if (!res) return;
    loadConversation(res);
    sendPrompt(text);
  };

  const deleteSession = async (id) => {
    await V.deleteSession(id);
    if (id === currentId) newChat();
    refreshSessions();
  };

  const clearHistory = async () => {
    setConfirmOpen(false);
    await V.clearHistory();
    newChat();
    refreshSessions();
  };

  const autoGrow = (e) => {
    const el = e.currentTarget;
    el.style.height = 'auto';
    el.style.height = Math.min(el.scrollHeight, 220) + 'px';
  };

  const closeTerm = useCallback(() => setTermOpen(false), []);

  const emptyVisible = items.length === 0;

  useEffect(() => {
    if (!emptyVisible) return;
    let alive = true;
    let outTimer = null;
    const iv = setInterval(() => {
      setHeroPhase('out');
      outTimer = setTimeout(() => {
        if (!alive) return;
        setHeroIdx((i) => (i + 1) % HERO_LINES.length);
        setHeroPhase('in');
      }, 470);
    }, 3000);
    return () => { alive = false; clearTimeout(outTimer); clearInterval(iv); };
  }, [emptyVisible]);
  const showIde = false;
  const showPreview = previewOpen;
  const closePanels = () => { setMcpOpen(false); setToolsOpen(false); };
  const rootName = (roots[0] || '').replace(/[\\/]+$/, '').split(/[\\/]/).pop() || 'Open folder';
  const ctxTotal = CTX_LIMITS[currentModel] || 131072;
  let ctxChars = input.length;
  for (const it of items) {
    let s = (it.text || '') + (it.content || '');
    if (Array.isArray(it.blocks)) s += it.blocks.map((b) => (b.text || b.label || b.note || '')).join('');
    if (Array.isArray(it.tasks)) s += it.tasks.map((t) => (t.text || t.label || '')).join('');
    ctxChars += s.length + 20;
  }
  const ctxUsed = Math.ceil((ctxChars + 6000) / 4);
  const ctxPct = ctxUsed / ctxTotal;

  const starters = [
    { icon: 'search', text: 'Scan my project and explain what it does' },
    { icon: 'wrench', text: 'Review my code for bugs and weak spots' },
    { icon: 'compose', text: 'Spin up something new inside my workspace' },
  ];
  const composerBody = usageLocked ? (
    <div className="composer-block">Your usage has exceeded for today, come back after 6 hours</div>
  ) : (
    <div className={'composer-wrap' + (emptyVisible && input.trim() ? ' big' : '')}>
      <div className="composer-card pill">
        <button className="chip chip-add" title="Open project folder" onClick={openFolder}>
          <Icon name="plus" size={14} />
        </button>
        <textarea
          id="input"
          ref={inputRef}
          rows="1"
          placeholder="Try anything…"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onInput={autoGrow}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onPaste={onPasteImage}
          onDrop={onDropImage}
          onDragOver={(e) => { if (Array.from((e.dataTransfer && e.dataTransfer.files) || []).some((x) => x.type.startsWith('image/'))) e.preventDefault(); }}
          onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); } else if (e.code === 'Space' && streaming && !input.trim()) { e.preventDefault(); V.stop(); } }}
        />
        {pendingImg && (
          <div className="img-chip">
            <img src={pendingImg} alt="pending image" />
            <button className="img-chip-x" title="Remove image" onClick={() => setPendingImg(null)}><Icon name="x" size={10} /></button>
          </div>
        )}
        <Dropdown
          id="btn-model"
          value={currentModel || WORKING_MODELS[0].value}
          options={WORKING_MODELS}
          onChange={pickModel}
          footer="Oxygen is built in — free to use, no key needed."
        />
        <CtxRing used={ctxUsed} total={ctxTotal} pct={ctxPct} />
        <button id="btn-send" className={`send-btn${streaming ? ' stop' : ''}`} title={streaming ? 'Stop' : 'Send'} disabled={usageLocked || (!streaming && !input.trim() && !pendingImg)} onClick={streaming ? () => V.stop() : send}>
          {streaming ? <Icon name="stop" size={13} /> : <Icon name="arrowUp" size={14} />}
        </button>
      </div>
      <div className={'composer-chips-wrap' + (emptyVisible ? ' fx fx-bot' : '')}>
        <button className="chip" title={roots[0] || 'Open a project folder'} onClick={openFolder}>
          <Icon name="folder" size={12} />
          <span>{rootName}</span>
        </button>
        <button className={`chip${termOpen ? ' active' : ''}`} title="Embedded terminal in the workspace folder" onClick={() => setTermOpen((o) => !o)}>
          <Icon name="terminal" size={12} />
          <span>Local shell</span>
        </button>
        <button className="chip" title="Run what you typed as a background task; keep chatting while it works" disabled={!input.trim() || streaming} onClick={sendBg}>
          <Icon name="reload" size={12} />
          <span>Background</span>
        </button>
        {bgList.length > 0 && <span className="chip chip-bg-count" title="Background tasks running"><Icon name="reload" size={12} />{bgList.length}</span>}
      </div>
      {!emptyVisible && <div className="composer-note">Oxygen is AI and can make mistakes. Please double-check responses.</div>}
    </div>
  );

  return (
    <div id="app">
      <div id="app-body" className={sbDrag ? 'dragging' : undefined}>
      <Sidebar
        userEmail={session?.email}
        onSignOut={onSignOut}
        onNew={newChat}
        onMcp={() => { closePanels(); setMcpOpen((o) => !o); }}
        onFiles={() => setIdeOpen((o) => !o)}
        onBrowser={() => setPreviewOpen((o) => !o)}
        onTools={() => { closePanels(); setToolsOpen((o) => !o); }}
        onMemory={() => { closePanels(); setMemOpen(true); }}
        bgList={bgList}
        onStopBg={(bgId) => { V.bgStop(bgId); }}
        sessions={sessions}
        currentId={currentId}
        onPick={pickSession}
        onDelete={deleteSession}
        onClear={() => setConfirmOpen(true)}
        mcpActive={mcpOpen}
        toolsActive={toolsOpen}
        filesActive={showIde}
        browserActive={showPreview}
        sbWidth={sbWidth}
        sbHidden={sbHidden}
        sbToggle={() => setSbHidden((o) => !o)}
        onResizeStart={startResize}
      />
          {showIde && <Ide log={ideLog} changeTrigger={ideChangeTrigger} openRequest={ideOpenRequest} />}
          {showPreview && <PreviewPane />}
      <McpPanel
        open={mcpOpen}
        mcp={mcp}
        onClose={() => setMcpOpen(false)}
        onAction={actMcp}
      />
      <ToolsPanel
        open={toolsOpen}
        onClose={() => setToolsOpen(false)}
      />
      <MemPanel
        open={memOpen}
        onClose={() => setMemOpen(false)}
      />

      <main id="main" className={[emptyVisible ? 'empty-mode' : '', (!emptyVisible && streaming) ? 'thinking-mode' : '', (showIde || showPreview) ? 'right' : ''].filter(Boolean).join(' ')}>
        <div className="chat-glow" aria-hidden="true">
          <span className="blob b1" />
          <span className="blob b2" />
          <span className="blob b3" />
          <span className="blob b4" />
        </div>
        <SeaWaves className="chat-sea" />
        <header id="chat-header">
          <div className="header-left">
            <div className="header-title">{title}</div>
          </div>
          <div className="header-right">
            {streaming && <span className="live" title="agent working"><span className="live-dot" /></span>}
            <WinControls />
          </div>
        </header>

        <section id="thread" className="thread" ref={threadRef}>
          {emptyVisible && (
            <div className={'empty' + (input.trim() ? ' fx-on' : '')}>
              <div className="fx fx-top">
                <div className="hero">
                  <h1 key={heroIdx} className={`hero-swap ${heroPhase}`}>
                    {HERO_LINES[heroIdx].split(' ').map((w, i) => (
                      <React.Fragment key={i}><span className="w" style={{ '--i': i }}>{w}</span>{' '}</React.Fragment>
                    ))}
                  </h1>
                </div>
              </div>
              {composerBody}
              <div className="fx fx-bot">
                <div className="starters">
                  {starters.map((s) => (
                    <button key={s.text} className="starter" onClick={() => sendPrompt(s.text)}>
                      <Icon name={s.icon} size={14} />
                      <span>{s.text}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
          {items.map((item) => <Message key={item.id} item={item} tasks={tasks} onRestore={handleRestore} onContinue={handleContinue} onRetry={handleRetry} />)}
        </section>

        {!emptyVisible && <footer id="composer">{composerBody}</footer>}

        <Terminal open={termOpen} onClose={closeTerm} />
      </main>

      <ConfirmModal open={confirmOpen} onCancel={() => setConfirmOpen(false)} onConfirm={clearHistory} />
      <CustomMcpModal 
        open={addMcpOpen} 
        onClose={() => setAddMcpOpen(false)} 
        onSubmit={async (data) => {
          setAddMcpOpen(false);
          setMcp(await V.getMcp({ save_custom: data }));
        }} 
      />
      {gate.shown && <GateOverlay phase={gate.phase} />}
      </div>
    </div>
  );
}

createRoot(document.getElementById('root')).render(<AuthGate />);
